export const STATEMENT_CSS = ":root {\n  /* The six colours of the identity */\n  --salt-obsidian: #05080a;   /* the ground; every surface sits on it */\n  --salt-slate: #0b1215;      /* deep panels, and the QR ink */\n  --salt-slate-light: #16211f; /* the lit slate: a chosen option, a menu row under the pointer */\n  --salt-brass: #c5a059;      /* the leading accent */\n  --salt-copper: #b87333;     /* the closing accent; gradients end on it */\n  --salt-salt: #f2f4f5;       /* text, and the field behind the QR */\n  --salt-mist: #7a8690;       /* muted labels and captions */\n  --salt-mist-light: #a6afb5; /* mist for running prose at 13px, where mist itself is too dark */\n  --salt-mist-bright: #b4bcc2; /* prose on a figure surface, one step under salt: a tile's note, a finding's body */\n\n  /* The desk's semantic colours, added 02 Sep 2026. Direction and risk need hues the six\n     brand colours do not carry, and each sits in the identity's temperature: verdigris is\n     copper's patina, ember is copper under heat, steel is slate lit. Copper stays the one\n     accent that marks the exception, so attention is copper and never a fourth hue. */\n  --salt-verdigris: #6fae97;  /* settled, owed to you, in cover */\n  --salt-ember: #d4694c;      /* owed by you, defaulted, breached */\n  --salt-steel: #8ea2b6;      /* pending, neutral, the cool second series */\n  --salt-brass-soft: #d8c79c; /* pale brass for a second tier */\n  /* THE FOURTH WORD, lifted from the desk on 22 Sep 2026 (it lived in salt-command's own layer from\n     v557, his instruction of 09 Sep 2026). Ember is copper under heat and sits dE 20.7 from it, so a\n     warning drawn in ember read as one more heading. This is a true alarm: breached, refused, a\n     figure that must not be missed. dE 32.5 from ember, 52.6 from copper, 5.6:1 on obsidian. */\n  --salt-alarm: #fa3c5a;\n\n  /* The books. Each is its own hue, and none of them is a SEMANTIC one: ember, verdigris,\n     steel and copper each mean something on the desk, so a product dot drawn in one would\n     read as a status rather than as a book. The violet and cyan families were retired at\n     v472 and are not used. Salt is the pale one and oil the golden one; oil is the same\n     value as --salt-brass, which is why its dot is hard to tell from ordinary chrome. */\n  --salt-product-salt: #e4e9ec;   /* near-white */\n  --salt-product-oil: #c5a059;    /* brass */\n  --salt-product-candy: #cf8fb4;  /* rose, hue 330 */\n  --salt-product-rice: #7b86cc;   /* indigo, hue 235 */\n  --salt-product-spare: #a8b06a;  /* olive, hue 68 */\n\n  /* Materials */\n  --salt-glass: rgba(255, 255, 255, 0.03);\n  --salt-glass-faint: rgba(255, 255, 255, 0.02);\n  --salt-line: rgba(197, 160, 89, 0.22);\n  --salt-line-faint: rgba(255, 255, 255, 0.06);\n  --salt-line-strong: rgba(197, 160, 89, 0.45); /* the hairline lifted: a chip's edge, a held or hovered control */\n  --salt-glass-hover: rgba(255, 255, 255, 0.06); /* a ghost, a row or a tab under the pointer */\n  --salt-highlight: rgba(255, 255, 255, 0.08);\n  --salt-focus-ring: 0 0 0 3px rgba(197, 160, 89, 0.18); /* the ring a focused control wears beside its brass hairline */\n  --salt-shadow: 0 32px 64px rgba(0, 0, 0, 0.55);\n  --salt-shadow-desk: 0 18px 40px rgba(0, 0, 0, 0.42); /* lighter, for a page of many panes */\n  --salt-well: rgba(0, 0, 0, 0.28);      /* inset: fields and meter tracks */\n  --salt-well-hover: rgba(0, 0, 0, 0.36); /* a well under the pointer */\n  --salt-veil: rgba(5, 8, 10, 0.86);     /* sticky and floating surfaces over content */\n  --salt-scrim: rgba(5, 8, 10, 0.55);    /* the page behind an open drawer */\n  --salt-pane: rgba(11, 18, 21, 0.66);   /* the glass fill when there is no backdrop to blur */\n  --salt-panel: rgb(28, 20, 13);         /* OPAQUE and warm: a sticky table head or label column inside a card.\n                                             A veil at .86 passes 14% of whatever scrolls under it, and the\n                                             only fill that cannot ghost is 1 (the desk's v567; here 22 Sep 2026) */\n  --salt-tap: 44px;                      /* the least a control may measure, either way */\n\n  /* Gradients. Brass to copper for marks and fills; white to copper for titles. */\n  --salt-gradient: linear-gradient(135deg, var(--salt-brass), var(--salt-copper));\n  --salt-gradient-title: linear-gradient(135deg, #ffffff 30%, var(--salt-copper) 100%);\n\n  /* Semantic aliases */\n  --salt-surface: var(--salt-obsidian);\n  --salt-text: var(--salt-salt);\n  --salt-text-muted: var(--salt-mist);\n  --salt-text-label: var(--salt-copper);\n\n  /* Typography */\n  --salt-font-display: 'Fraunces', Georgia, 'Times New Roman', serif;\n  --salt-font-mono: 'JetBrains Mono', 'Cascadia Mono', Consolas, monospace;\n\n  --salt-text-xs: 11px;\n  --salt-text-sm: 13px;\n  --salt-text-md: 15px;\n  --salt-text-lg: 17px;\n  --salt-text-xl: 24px;\n  --salt-text-2xl: 34px;\n  --salt-text-3xl: 48px;\n  --salt-text-4xl: 64px;\n  --salt-text-5xl: 88px;\n\n  /* Space, radius */\n  --salt-space-1: 4px;\n  --salt-space-2: 8px;\n  --salt-space-3: 12px;\n  --salt-space-4: 16px;\n  --salt-space-5: 24px;\n  --salt-space-6: 32px;\n  --salt-space-7: 48px;\n\n  --salt-radius-sm: 12px;\n  --salt-radius-md: 16px;\n  --salt-radius-lg: 24px;\n  --salt-radius-xl: 36px;\n  --salt-radius-pill: 100px;\n}\n*{box-sizing:border-box}\nhtml{-webkit-text-size-adjust:100%}\nbody{\n  margin:0;padding:44px 20px 60px;\n  color:var(--salt-text);\n  background:\n    radial-gradient(1200px 640px at 82% -12%, rgba(184,115,51,.16) 0%, transparent 62%),\n    radial-gradient(900px 560px at -10% 6%, rgba(197,160,89,.10) 0%, transparent 58%),\n    var(--salt-obsidian);\n  background-attachment:fixed;\n  font-family:var(--salt-font-display);\n  font-size:var(--salt-text-md);line-height:1.6;-webkit-font-smoothing:antialiased}\n\n/* FIGURES IN MONO, SENTENCES IN THE DISPLAY FACE. Decision 3 of the identity, and the whole\n   figure vocabulary of a statement is listed here once. */\n.dt,.q,.amt,.u,.tr span:last-child,.owedv,.who,.idx td,.mini td,.mini th,.pw,\n.ok,.due,.pend,.cx,.owedunits,.gift,.nilamt,.eyebrow,.whol,th,.rvh,.slab\n  {font-family:var(--salt-font-mono);font-variant-numeric:tabular-nums}\n\n.w{max-width:620px;margin:0 auto}\n.eyebrow{font-size:var(--salt-text-xs);letter-spacing:.32em;color:var(--salt-copper);\n  font-weight:700;margin:0 0 10px;text-transform:uppercase}\nh1{margin:0;font-size:var(--salt-text-2xl);font-weight:600;letter-spacing:-.01em;line-height:1.12;\n  font-family:var(--salt-font-display)}\n.meta{color:var(--salt-text-muted);font-size:var(--salt-text-sm);margin:10px 0 0}\n.whol{font-size:var(--salt-text-xs);letter-spacing:.2em;text-transform:uppercase;\n  color:var(--salt-copper);font-weight:700;margin:0}\n.whol.gap1{margin:26px 0 0}.whol.gap2{margin:30px 0 0}\n.who{margin:8px 0 4px;font-size:var(--salt-text-lg);font-weight:700;color:var(--salt-text);\n  letter-spacing:.06em}\n/* brass leads the hairlines: decision 1 */\n.rule{height:1px;background:var(--salt-line);margin:24px 0 4px;border:0}\n\n.tblw{overflow-x:auto;-webkit-overflow-scrolling:touch}\ntable{width:100%;border-collapse:collapse;min-width:340px}\ntable.rft{margin-top:10px}\nth{font-size:var(--salt-text-xs);letter-spacing:.16em;text-transform:uppercase;\n  color:var(--salt-text-muted);font-weight:700;padding:0 0 10px;text-align:right;white-space:nowrap}\nth.l{text-align:left}\ntd{padding:15px 0;border-bottom:1px solid var(--salt-line-faint);text-align:right;vertical-align:top}\ntd.l{text-align:left}\n.dt{font-size:var(--salt-text-md);color:var(--salt-text)}\n.nodt{color:var(--salt-text-muted)}\n.sub2{font-size:var(--salt-text-sm);color:var(--salt-text-muted);margin-top:4px;\n  font-family:var(--salt-font-display)}\n.rsn{font-size:var(--salt-text-sm);color:var(--salt-text-muted);font-family:var(--salt-font-display)}\n.q{font-size:var(--salt-text-md);color:var(--salt-mist-light)}\n.u{font-size:var(--salt-text-xs);color:var(--salt-text-muted);margin-left:5px}\n/* v782: THE BOOK'S MARK, beside the quantity it qualifies. It takes the row's own colour rather\n   than the book's hue, because a statement is read on paper as often as on a screen and a hue\n   that survives one may not survive the other; the SHAPE is what carries the meaning, which is\n   why the shape is also the accessible name. .sr is the name for a screen reader and is off the\n   page rather than display:none, which would take it out of the accessibility tree as well. */\n.pm{display:inline-flex;align-items:center;margin-right:5px;vertical-align:-1px;color:var(--salt-text-muted)}\n.pm .psym{display:block}\n.sr{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}\n.amt{font-size:var(--salt-text-lg);font-weight:700;color:var(--salt-text)}\n\n/* THE THREE WORDS. Each is a mono word in its colour; nothing here is a filled badge. */\n.ok{font-size:var(--salt-text-sm);color:var(--salt-verdigris);letter-spacing:.02em}\n.due{font-size:var(--salt-text-sm);font-weight:700;color:var(--salt-ember);white-space:nowrap}\n.pend{color:var(--salt-steel);font-weight:700;font-size:var(--salt-text-sm);letter-spacing:.02em}\n.owedunits{font-size:var(--salt-text-sm);color:var(--salt-verdigris);margin-top:5px;\n  font-weight:600;white-space:nowrap}\n.cx{color:var(--salt-text-muted);font-weight:700;font-size:var(--salt-text-sm);letter-spacing:.02em}\n.cxn{color:var(--salt-text-muted);font-weight:600}\n.cxr{text-decoration:line-through;text-decoration-thickness:1px;opacity:.45}\n.gift{font-size:var(--salt-text-sm);color:var(--salt-mist-light);letter-spacing:.02em;white-space:nowrap}\n.nilamt{color:var(--salt-text-muted);font-weight:400}\n\n.tot{margin-top:30px}\n.tr{display:flex;justify-content:space-between;align-items:baseline;gap:14px;padding:8px 0;\n  font-size:var(--salt-text-sm);color:var(--salt-text-muted)}\n.tr span:last-child{color:var(--salt-text);white-space:nowrap}\n.tr.big{margin-top:10px;padding-top:16px;border-top:1px solid var(--salt-line);\n  font-size:var(--salt-text-xl);font-weight:700;color:var(--salt-text)}\n.tr.big span:last-child{color:var(--salt-ember)}\n.tr.big.clear span:last-child{color:var(--salt-verdigris)}\n.tr.sub{color:var(--salt-text-muted);font-size:var(--salt-text-sm)}\n\n/* GLASS ONCE: a pane is white 3% with a brass hairline. A pane inside a pane is flat. */\n.owed,.rec{margin-top:26px;border:1px solid var(--salt-line);border-radius:var(--salt-radius-md);\n  background:var(--salt-glass)}\n.owed{padding:20px 22px}\n.owedl{margin:0;font-size:var(--salt-text-xs);letter-spacing:.2em;text-transform:uppercase;\n  color:var(--salt-copper);font-weight:700}\n.owedv{margin:8px 0 0;font-size:var(--salt-text-2xl);font-weight:700;color:var(--salt-verdigris);\n  letter-spacing:-.01em}\n.owedv>span:last-child{font-size:var(--salt-text-md);font-weight:600;margin-left:6px;color:var(--salt-text-muted)}\n.owedn{margin:12px 0 0;font-size:var(--salt-text-sm);color:var(--salt-text-muted);line-height:1.6}\n.rec{padding:22px 22px 8px}\n.recl{margin:0 0 18px;font-size:var(--salt-text-xs);letter-spacing:.2em;text-transform:uppercase;\n  color:var(--salt-copper);font-weight:700}\n.stp{display:flex;gap:14px;margin-bottom:20px}\n.stpn{flex:0 0 24px;height:24px;border-radius:var(--salt-radius-pill);border:1px solid var(--salt-line);\n  color:var(--salt-brass);font-size:var(--salt-text-xs);font-weight:700;font-family:var(--salt-font-mono);\n  display:flex;align-items:center;justify-content:center;line-height:1}\n.stpb{flex:1 1 auto;min-width:0}\n.stpt{margin:0;font-size:var(--salt-text-md);font-weight:600;color:var(--salt-text);line-height:1.5}\n.stpd{margin:7px 0 0;font-size:var(--salt-text-sm);color:var(--salt-text-muted);line-height:1.65}\ntable.mini{width:100%;border-collapse:collapse;margin-top:10px;min-width:0}\ntable.mini th{font-size:var(--salt-text-xs);letter-spacing:.14em;padding:0 0 6px;color:var(--salt-text-muted)}\ntable.mini td{padding:8px 0;font-size:var(--salt-text-sm);border-bottom:1px solid var(--salt-line-faint);\n  color:var(--salt-mist-light)}\ntable.mini tr.tot td{border-bottom:0;border-top:1px solid var(--salt-line);font-weight:700;\n  color:var(--salt-text);padding-top:9px}\ntable.mini tr.sub td{border-bottom:0;color:var(--salt-text);font-weight:700}\nb.short{color:var(--salt-ember)}\n.recn{margin:2px 0 16px;font-size:var(--salt-text-sm);color:var(--salt-text-muted);line-height:1.65;\n  border-top:1px solid var(--salt-line-faint);padding-top:14px}\n.note{margin-top:34px;font-size:var(--salt-text-sm);color:var(--salt-text-muted);line-height:1.7}\n\n/* The QR block. A code on paper is only useful if what it opens is written beside it. */\n.qrb{margin-top:34px;display:flex;gap:20px;align-items:center;\n  border-top:1px solid var(--salt-line);padding-top:26px}\n.qrb svg{border-radius:var(--salt-radius-sm);display:block;flex:0 0 auto}\n.qrt{margin:0;font-size:var(--salt-text-sm);color:var(--salt-text-muted);line-height:1.7}\n.qrt code{font-family:var(--salt-font-mono);font-size:var(--salt-text-xs);color:var(--salt-brass);\n  word-break:break-all}\n@media (max-width:460px){.qrb{flex-direction:column;align-items:flex-start}}\n\n@media print{\n  body{background:#fff;color:#111;padding:24px}\n  .eyebrow,.whol,.owedl,.recl{color:#8a5a20}\n  .meta,.note,.sub2,.u,.nilamt,.cxn,.cx,.stpd,.recn,.qrt,.rsn,.nodt{color:#555}\n  .q,.mini td{color:#333}\n  .ok,.owedunits,.tr.big.clear span:last-child,.owedv{color:#1d6b52}\n  .due,.tr.big span:last-child,b.short{color:#a8442c}\n  .pend{color:#41586e}\n  .gift{color:#555}\n  td{border-color:#ddd}.rule,.tr.big{border-color:#c9ad74}\n  .tr{color:#333}.tr span:last-child,.amt,.dt{color:#111}\n  .owed,.rec{background:#fbfaf7;border-color:#d8c79c}\n  .stpn{color:#8a5a20;border-color:#d8c79c}\n  .stpt{color:#111}\n  .qrb{border-color:#ddd}.qrt code{color:#8a5a20}\n}";
export const SITE_RECIPES = "/* ---- Pill button ---- */\n\n.salt-pill {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  min-height: var(--salt-tap);\n  text-decoration: none;\n  text-align: center;\n  background: var(--salt-gradient);\n  color: var(--salt-obsidian);\n  border: none;\n  border-radius: var(--salt-radius-pill);\n  font-family: var(--salt-font-mono);\n  font-weight: 700;\n  letter-spacing: 0.1em;\n  text-transform: uppercase;\n  cursor: pointer;\n  box-shadow: 0 8px 24px rgba(184, 115, 51, 0.3);\n  transition: transform 0.2s, box-shadow 0.2s;\n}\n.salt-pill--md { padding: 16px 40px; font-size: 14px; }\n.salt-pill--sm { padding: 10px 20px; font-size: 11.5px; }\n.salt-pill:hover { transform: translateY(-2px); box-shadow: 0 12px 32px rgba(184, 115, 51, 0.4); }\n.salt-pill:active { transform: translateY(0); box-shadow: 0 8px 24px rgba(184, 115, 51, 0.3); }\n.salt-pill:focus-visible { outline: 2px solid var(--salt-brass); outline-offset: 3px; }\n.salt-pill:disabled {\n  opacity: 0.45;\n  cursor: not-allowed;\n  transform: none;\n  box-shadow: none;\n}\n@media (prefers-reduced-motion: reduce) {\n  .salt-pill { transition: none; }\n  .salt-pill:hover { transform: none; }\n}\n\n/* ---- Fields ---- */\n\n.salt-field { display: flex; flex-direction: column; gap: var(--salt-space-2); }\n/* stated twice, so a page's own \".x label\" rule cannot outrank it */\n.salt-field__label,\nlabel.salt-field__label {\n  font-family: var(--salt-font-mono);\n  font-size: 11px;\n  font-weight: 500;\n  letter-spacing: 0.14em;\n  text-transform: uppercase;\n  color: var(--salt-copper);\n}\n.salt-field__input {\n  /* a well, not glass (principle 4), 16px so a phone never zooms on focus and 44px tall\n     (principle 7); the recipe said 15px on glass until 22 Sep 2026 */\n  background: var(--salt-well);\n  border: 1px solid var(--salt-line-faint);\n  border-radius: var(--salt-radius-sm);\n  padding: 12px 16px;\n  min-height: var(--salt-tap);\n  color: var(--salt-salt);\n  font-family: var(--salt-font-display);\n  font-size: 16px;\n  line-height: 1.4;\n  color-scheme: dark;\n  width: 100%;\n}\n.salt-field__input::placeholder { color: var(--salt-mist); opacity: 0.7; }\n.salt-field__input:focus-visible { outline: none; border-color: var(--salt-brass); box-shadow: var(--salt-focus-ring); }\n.salt-field__input--mono { font-family: var(--salt-font-mono); font-variant-numeric: tabular-nums; }\n.salt-field__input--error { border-color: rgba(184, 115, 51, 0.7); }\n.salt-field__hint { font-family: var(--salt-font-mono); font-size: 11px; color: var(--salt-mist); }\n.salt-field__error { font-family: var(--salt-font-mono); font-size: 11px; color: var(--salt-copper); }\n\n/* ---- Tab strip ---- */\n\n.salt-tabs { display: flex; gap: var(--salt-space-2); flex-wrap: wrap; }\n.salt-tabs__pill {\n  font-family: var(--salt-font-mono);\n  font-size: 11.5px;\n  font-weight: 500;\n  letter-spacing: 0.12em;\n  text-transform: uppercase;\n  color: var(--salt-mist);\n  background: transparent;\n  border: 1px solid var(--salt-line-faint);\n  border-radius: var(--salt-radius-pill);\n  padding: 8px 16px;\n  cursor: pointer;\n}\n.salt-tabs__pill:hover { color: var(--salt-brass); border-color: var(--salt-line); }\n/* The active pill is also read from ARIA, so a strip carrying role=\"tab\" needs no second class and\n   a consumer's older rule on its own state class cannot outrank it. */\n.salt-tabs__pill--active, .salt-tabs__pill[aria-selected=\"true\"] { color: var(--salt-salt); background: var(--salt-glass); border-color: var(--salt-line); }\n.salt-tabs__pill--active:hover, .salt-tabs__pill[aria-selected=\"true\"]:hover { color: var(--salt-salt); }\n.salt-tabs__pill:focus-visible { outline: 2px solid var(--salt-brass); outline-offset: 2px; }\n.salt-tabs__count { color: var(--salt-copper); margin-left: 8px; }\n\n/* ---- Status chip: a mono word in its colour with a hairline, never a fill. The tone is ONE\n   variable, --salt-status-tone, which the modifiers set and a consumer's own state class may set\n   too (the desk binds .tag.paid to it), and the hairline is the word's own colour. Sized to the\n   desk's ledger row (22 Sep 2026): 11px, .12em, 2px 9px. ---- */\n\n.salt-status {\n  --salt-status-tone: var(--salt-brass);\n  display: inline-block;\n  font-family: var(--salt-font-mono);\n  font-size: var(--salt-text-xs);\n  font-weight: 500;\n  letter-spacing: 0.12em;\n  text-transform: uppercase;\n  color: var(--salt-status-tone);\n  background: transparent;\n  border: 1px solid currentColor;\n  border-radius: var(--salt-radius-pill);\n  padding: 2px 9px;\n}\n.salt-status--brass { --salt-status-tone: var(--salt-brass); }\n.salt-status--copper { --salt-status-tone: var(--salt-copper); }\n.salt-status--mist { --salt-status-tone: var(--salt-mist); }\n.salt-status--salt { --salt-status-tone: var(--salt-salt); }\n\n/* ---- Ghost button: the quiet control. The pill books or produces; this navigates, filters\n   and dismisses. Its colour is one variable a consumer may bind; lit, it is brass on a lifted\n   hairline (the desk's Update); tight, it keeps its 44px height and drops the width and padding\n   for a table cell; on, it is read from aria-pressed as well as its own class. ---- */\n\n.salt-ghost {\n  --salt-ghost-tone: var(--salt-mist);\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 8px;\n  min-height: var(--salt-tap);\n  min-width: var(--salt-tap);\n  padding: 8px 16px;\n  background: transparent;\n  border: 1px solid var(--salt-line-faint);\n  border-radius: var(--salt-radius-pill);\n  color: var(--salt-ghost-tone);\n  font-family: var(--salt-font-mono);\n  font-size: var(--salt-text-xs);\n  font-weight: 500;\n  letter-spacing: 0.1em;\n  text-transform: uppercase;\n  cursor: pointer;\n  text-decoration: none;\n  transition: color 0.16s, border-color 0.16s, background 0.16s;\n}\n.salt-ghost:hover { color: var(--salt-brass); border-color: var(--salt-line); background: transparent; transform: none; }\n.salt-ghost--on, .salt-ghost[aria-pressed=\"true\"] { color: var(--salt-salt); background: var(--salt-glass); border-color: var(--salt-line); }\n.salt-ghost--lit { --salt-ghost-tone: var(--salt-brass); border-color: var(--salt-line-strong); }\n.salt-ghost--tight { min-width: 0; padding: 3px 9px; }\n.salt-ghost--sm { min-height: 32px; padding: 4px 12px; font-size: var(--salt-text-xs); }\n.salt-ghost--danger:hover { color: var(--salt-ember); border-color: rgba(212, 105, 76, 0.55); background: rgba(212, 105, 76, 0.08); }\n.salt-ghost:focus-visible { outline: 2px solid var(--salt-brass); outline-offset: 2px; }\n.salt-ghost:disabled { opacity: 0.45; cursor: not-allowed; }\n\n/* ---- Status chip, the added tones ---- */\n\n.salt-status--verdigris { --salt-status-tone: var(--salt-verdigris); }\n.salt-status--ember { --salt-status-tone: var(--salt-ember); }\n.salt-status--steel { --salt-status-tone: var(--salt-steel); }\n.salt-status--alarm { --salt-status-tone: var(--salt-alarm); }\n.salt-status--dashed { border-style: dashed; }\n.salt-status--dotted { border-style: dotted; }\n";
export const FONT_FACE_CSS = "/* THE BRAND FACES, SELF-HOSTED, AND THE ONLY WAY THEY LOAD (his instruction of 22 Sep 2026: no Google\n   Fonts). The files are Google's own latin subsets, fetched once and kept in src/fonts/ beside this\n   file with their OFL licences; nothing here loads off another origin. A page that LINKS this file\n   resolves fonts/ against it; a page that INLINES these rules (the desk, the Counter, QR Command)\n   serves fonts/ beside itself. Both are variable fonts and the weight ranges below are the files'\n   own, so a 700 resolves to the face and is never synthesised. Symbols outside the latin range (a\n   tick, a triangle) fall to the system face, as they always did. */\n@font-face {\n  font-family: 'Fraunces';\n  font-style: normal;\n  font-weight: 100 900;\n  font-display: swap;\n  src: url(/fonts/fraunces-latin.woff2) format('woff2');\n  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;\n}\n@font-face {\n  font-family: 'JetBrains Mono';\n  font-style: normal;\n  font-weight: 400 800;\n  font-display: swap;\n  src: url(/fonts/jetbrains-mono-latin.woff2) format('woff2');\n  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;\n}\n";
